package com.mamtrex.hospital.nursing;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/nursing-observations") public class NursingObservationController { private final NursingObservationRepository repo; private final AuditService audit; public NursingObservationController(NursingObservationRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String patientId, @jakarta.validation.constraints.NotBlank String temperatureC, @jakarta.validation.constraints.NotBlank String bloodPressure, @jakarta.validation.constraints.NotBlank String heartRate, @jakarta.validation.constraints.NotBlank String note){} @PostMapping public NursingObservation create(@Valid @RequestBody Request r){var e=repo.save(new NursingObservation(r.patientId(), r.temperatureC(), r.bloodPressure(), r.heartRate(), r.note()));audit.record("CREATE","NursingObservation",e.getId().toString(),"created");return e;} @GetMapping public List<NursingObservation> list(){return repo.findAll();} @GetMapping("/{id}") public NursingObservation get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("NursingObservation not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("NursingObservation not found: "+id);repo.deleteById(id);audit.record("DELETE","NursingObservation",id.toString(),"deleted");} }
